{"command": "python3 -c "
from PIL import Image
img = Image.open('/opt/exam/grader/golden.png')
w, h = img.size

# Find darkest pixels in the fixture area (approx x=120-360, y=125-225)
darkest = []
for y in range(125, 226):
    for x in range(120, 361):
        px = img.getpixel((x, y))
        b = sum(px)
        if b < 250:
            darkest.append((b, x, y, px))
darkest.sort()
for b, x, y, px in darkest[:30]:
    print(f'({x},{y}): brightness={b}, color={px}')
""}

